/* eslint-disable no-console */
// JS8 demodulator checks: frames generated by the (reference-checked) encoder, placed in a
// period of 12 kHz audio with noise, come back with the right text, type, frequency and
// time; two stations at once; the fast submode; and silence and noise alone decode nothing.
// Run: npm run check:js8demod

import { fftMixed } from "@/lib/dsp/fft-mixed";
import { JS8_SUBMODES, js8EncodeFrame, js8Waveform, type Js8Submode } from "@/lib/digital/js8";
import { js8DecodeAudio } from "@/lib/digital/js8demod";

let failed = 0;
function ok(cond: boolean, what: string, extra?: unknown): void {
  if (cond) {
    console.log(`  ok    ${what}`);
  } else {
    failed++;
    console.log(`  FAIL  ${what}`, extra ?? "");
  }
}
function eq(a: unknown, b: unknown, what: string): void {
  ok(JSON.stringify(a) === JSON.stringify(b), what, `expected ${JSON.stringify(b)}, got ${JSON.stringify(a)}`);
}
function gaussian(seed: number): () => number {
  let s = seed >>> 0;
  const u = () => {
    s = (Math.imul(s, 1664525) + 1013904223) >>> 0;
    return (s + 1) / 4294967297;
  };
  return () => Math.sqrt(-2 * Math.log(u())) * Math.cos(2 * Math.PI * u());
}

const FS = 12_000;

/** A period of audio with frames in it. */
function period(
  frames: { text: string; type: number; hz: number; dtS?: number; amplitude?: number }[],
  opts: { submode?: Js8Submode; noise?: number; seed?: number } = {},
): Float32Array {
  const submode = opts.submode ?? "A";
  const p = JS8_SUBMODES[submode];
  const audio = new Float32Array(p.periodS * FS);
  if (opts.noise) {
    const g = gaussian(opts.seed ?? 1);
    for (let i = 0; i < audio.length; i++) audio[i] = opts.noise * g();
  }
  for (const f of frames) {
    const { tones } = js8EncodeFrame(f.text, f.type, submode);
    const w = js8Waveform(tones, { sampleRate: FS, baseHz: f.hz, submode, amplitude: f.amplitude ?? 0.3 });
    const start = Math.round((p.startS + (f.dtS ?? 0)) * FS);
    for (let i = 0; i < w.length && start + i < audio.length; i++) audio[start + i]! += w[i]!;
  }
  return audio;
}

// ---------------------------------------------------------------------------
console.log("the mixed-radix FFT");
// ---------------------------------------------------------------------------
{
  for (const n of [8, 12, 15, 32, 3840, 3200]) {
    const re = new Float64Array(n);
    const im = new Float64Array(n);
    // A single tone at bin 3 should land in bin 3.
    for (let i = 0; i < n; i++) re[i] = Math.cos((2 * Math.PI * 3 * i) / n);
    fftMixed(re, im, -1);
    let best = 0;
    for (let k = 1; k < n; k++) if (Math.hypot(re[k]!, im[k]!) > Math.hypot(re[best]!, im[best]!)) best = k;
    const mag = Math.hypot(re[3]!, im[3]!);
    ok((best === 3 || best === n - 3) && Math.abs(mag - n / 2) < 1e-6 * n, `N=${n}: a real tone at bin 3 transforms to bins 3 and N-3 with magnitude N/2`, `${best} ${mag}`);
    // Inverse brings it back (times N).
    fftMixed(re, im, 1);
    let err = 0;
    for (let i = 0; i < n; i++) err = Math.max(err, Math.abs(re[i]! / n - Math.cos((2 * Math.PI * 3 * i) / n)));
    ok(err < 1e-9, `N=${n}: inverse of forward is identity (times N)`, err);
  }
}

// ---------------------------------------------------------------------------
console.log("\none clean frame");
// ---------------------------------------------------------------------------
{
  const t0 = Date.now();
  const d = js8DecodeAudio(period([{ text: "CQCQCQ+-ab12", type: 3, hz: 1500 }]), { sampleRate: FS });
  const ms = Date.now() - t0;
  console.log("        decodes:", JSON.stringify(d.map((x) => ({ f: +x.freqHz.toFixed(1), dt: +x.dtS.toFixed(3), snr: x.snrDb, sync: x.sync, hard: x.hardErrors, pass: x.pass, text: x.text }))));
  eq(d.length, 1, "one frame decodes");
  eq(d[0]?.text, "CQCQCQ+-ab12", "with its text");
  eq(d[0]?.frameType, 3, "and its frame type");
  ok(Math.abs((d[0]?.freqHz ?? 0) - 1500) <= 1.6, "at its frequency within a bin and a half", d[0]?.freqHz);
  ok(Math.abs(d[0]?.dtS ?? 9) <= 0.05, "and DT near 0 for a punctual station", d[0]?.dtS);
  eq(d[0]?.sync, 21, "all 21 sync symbols on their tones");
  eq(d[0]?.pass, 1, "on the first pass");
  console.log(`        (${ms} ms for a 15 s period on this machine)`);
}

// ---------------------------------------------------------------------------
console.log("\noffsets, noise, two stations");
// ---------------------------------------------------------------------------
{
  const off = js8DecodeAudio(period([{ text: "K9XYZEN61AA0", type: 1, hz: 2101.3, dtS: 0.8 }]), { sampleRate: FS });
  console.log("        decodes:", JSON.stringify(off.map((x) => ({ f: +x.freqHz.toFixed(1), dt: +x.dtS.toFixed(3), snr: x.snrDb, sync: x.sync, hard: x.hardErrors, pass: x.pass }))));
  eq(off[0]?.text, "K9XYZEN61AA0", "a station 0.8 s late and 1.3 Hz off a bin decodes");
  ok(Math.abs((off[0]?.freqHz ?? 0) - 2101.3) <= 1, "frequency to the half-hertz search", off[0]?.freqHz);
  ok(Math.abs((off[0]?.dtS ?? 0) - 0.8) <= 0.06, "DT to a quarter symbol", off[0]?.dtS);

  const noisy = js8DecodeAudio(period([{ text: "Hello1234567", type: 5, hz: 1000, amplitude: 0.05 }], { noise: 0.3, seed: 7 }), { sampleRate: FS });
  eq(noisy[0]?.text, "Hello1234567", "a weak frame (amplitude 0.05 in noise of 0.3, about -16 dB in 2.5 kHz) decodes");
  ok((noisy[0]?.snrDb ?? 0) < -5 && (noisy[0]?.snrDb ?? -99) > -28, "with a plausible SNR", noisy[0]?.snrDb);

  const two = js8DecodeAudio(period([{ text: "MNOPQRSTUVWX", type: 2, hz: 900 }, { text: "yzab98765432", type: 6, hz: 2400, dtS: 0.3, amplitude: 0.15 }], { noise: 0.05, seed: 3 }), { sampleRate: FS });
  const texts = two.map((d) => d.text).sort();
  eq(texts, ["MNOPQRSTUVWX", "yzab98765432"], "two stations in one period both decode");
}

// ---------------------------------------------------------------------------
console.log("\nthe fast submode, and nothing");
// ---------------------------------------------------------------------------
{
  const fast = js8DecodeAudio(period([{ text: "0123456789AB", type: 0, hz: 1800 }], { submode: "B", noise: 0.02, seed: 5 }), { sampleRate: FS, submode: "B" });
  eq(fast[0]?.text, "0123456789AB", "fast mode (10 s, 10 baud, the second Costas set) decodes");

  eq(js8DecodeAudio(new Float32Array(15 * FS), { sampleRate: FS }).length, 0, "silence decodes nothing");
  const g = gaussian(11);
  const noise = new Float32Array(15 * FS);
  for (let i = 0; i < noise.length; i++) noise[i] = 0.3 * g();
  eq(js8DecodeAudio(noise, { sampleRate: FS }).length, 0, "noise alone decodes nothing");
}

console.log("");
if (failed > 0) {
  console.log(`${failed} FAILED`);
  process.exit(1);
}
console.log("all JS8 demodulator assertions passed");
